(286, 'APP202610300015', 'Mihir jain', 'mihirjain5555@gmail.com', '7568544515', '9785253552', 'Male', '2003-06-30', 'Samrirdhi apartment kaveri path', 'Jaipur', 'Rajasthan', '302020', 'Bcom', NULL, NULL, NULL, NULL, 'Operations', NULL, 'walkin', NULL, 'manager_feedback_received', 'pending', '2026-10-30 10:18:10', '2026-10-30 13:10:20', NULL, NULL, NULL, NULL, 'uploads/photos/1793355490_photo_d6c360d6-9b96-4f7d-918b-567bec4bf5d6.jpeg', 'uploads/resumes/1793355490_resume_MIHIR_JAIN_CV_updated.pdf', 'Rajesh kumar jain', '9785253552', 23, 'Single', 'Samrirdhi apartment kaveri path', NULL, 'To build a successful career in Operations Management by utilising my analytical, problem-solving, and organisational skills. I aim to contribute to efficient business operations, process improvement, and team coordination while continuously learning and growing professionally within the organisation.', NULL, NULL, NULL, 'Analytical and problem-solving skills\r\nAttention to detail and accuracy\r\nTime management and prioritisation\r\nStrong organisational skills\r\nAbility to work under pressure\r\nTeam coordination and collaboration\r\nQuick learner and adaptable', 'I used to take extra time to make decisions, but I am improving my decision-making skills.', NULL, NULL, NULL, NULL, '267423181954', NULL, NULL, NULL, 'Watching movies and series', 'Basic knowledge of excel \r\nOperating computer \r\nPower BI', NULL, 'No issue', NULL, NULL, NULL),
(287, 'APP202610300016', 'Yashvardhan dagur', 'daguryash69@gmail.com', '9116886244', NULL, 'Male', '2005-01-20', 'Vaishali nagar,bajri mandi', 'Jaipur', 'Rajasthan', '302021', 'Graduation', NULL, NULL, NULL, NULL, 'Operations', NULL, 'walkin', NULL, 'manager_feedback_received', 'pending', '2026-10-30 11:24:08', '2026-10-30 13:16:29', NULL, NULL, NULL, NULL, 'uploads/photos/1793359448_photo_13714.png', 'uploads/resumes/1793359448_resume_cdbdb4fe-fa88-4705-9090-3523937c8117.pdf', 'Bhagat Singh dagur', NULL, 21, 'Single', 'Hindaun city, government hospital', NULL, NULL, NULL, NULL, NULL, 'My strengths are that I am a quick learner, hardworking, and self-motivated person. I have good listening skills, a positive attitude, and patience. I can work well in a team, adapt to new situations, and handle challenges calmly. I am always ready to learn new things and improve my skills.', 'As a fresher, I believe I still have many things to learn. Sometimes I feel nervous in new situations, but I am working on improving my confidence and communication skills. I am always ready to learn from my mistakes and improve myself.', NULL, NULL, NULL, NULL, '68374930 9920', NULL, NULL, NULL, 'My hobbies are listening to music, reading books, learning new things, and improving my communication skills. I also like spending time with my family. These activities help me stay positive and motivated.', 'I have basic computer knowledge. I am familiar with using a computer, browsing the internet, sending emails, and working with MS Word and basic Excel. I also have RS-CIT certification. I am willing to learn new software and improve my computer skills.', NULL, 'No health issues', NULL, NULL, NULL),
