INSERT INTO `interview_feedback` (`id`, `round_id`, `candidate_id`, `manager_id`, `remark_text`, `recommendation`, `created_at`) VALUES
(26, 32, 38, 10, 'Hold', 'hold', '2026-08-26 07:08:57'),
(27, 33, 37, 10, 'Candidate possesses decent communication skills and is better suited for a Reservation Sales role rather than a TL position. Comfortable with 6-day working and rotational shifts. Has basic knowledge of destinations, good sales aptitude, and experience using Outlook and Excel.Looking for salary above 40 k but negotiable also', 'next_round', '2026-08-26 07:20:20'),
(28, 35, 39, 10, 'The candidate has satisfactory communication skills and is proficient in Microsoft Outlook and Excel. He is comfortable working in shifts and with rotational weekly offs. He is available for immediate joining and is expecting a salary of ?32,000+.\"', 'next_round', '2026-08-26 07:31:32'),
(29, 34, 38, 11, 'She is undergraduate, communication is good, interested in sales. Ok for 6 days week & shift timings. Leaves alone in Jaipur. Family is in Andhra. On hold for now.', 'hold', '2026-08-26 08:05:52'),
(30, 36, 39, 11, 'He is good in terms of communication, skills & learning abilities. Has BPO experience as well. Can be considered if he agrees to join in 21600 in hand, he is asking for 23 K in hand. Ready for 6 days & shift timings as well.', 'select', '2026-08-26 08:30:30'),
(31, 37, 40, 11, 'He has good communication, worked for 6 months in health sector. Interested in sales, comfortable for 6 days a week, comfortable with shift timings. Ok for our basic salary.', 'next_round', '2026-08-26 11:58:30'),
(32, 38, 40, 10, 'He has good communication, worked for 6 months in health sector. Interested in sales, comfortable for 6 days a week, comfortable with shift timings. Looking for salary more than 18 k and can join immediately.', 'next_round', '2026-08-26 12:28:59'),
(33, 38, 40, 10, 'He has good communication, worked for 6 months in health sector. Interested in sales, comfortable for 6 days a week, comfortable with shift timings. Ok to join immediately and looking for salary above 18 k', 'select', '2026-08-26 12:38:36'),
(34, 39, 37, 11, 'He has travel experience & a little destination knowledge as well. Not suitable for TL profile, lack of maturity, he does not seem to be sincere & focused. Ok for sales executive role but salary expectation is high, asking for 40 K in hand. So not suitatble.', 'reject', '2026-08-27 07:16:48'),
(35, 40, 41, 11, 'Deepak seems decent, enthusiastic looking for a better opportunity in sales. Has 4 years\' experience but not relevant since industry & work profile is different.\r\nCommunication is average. ok for 6 days shift & shift timings. Asking for 25 CTC. Can be considered as executive reservation.', 'next_round', '2026-08-27 08:30:37'),
(36, 41, 42, 10, 'Candidate has decent communication skills and is actively seeking employment due to financial responsibilities at home. A complete fresher, they have completed a computer course and possess basic knowledge of MS Excel and email handling. Comfortable with rotational shifts and weekly offs, and currently looking for a salary of ?22,000 per month.', 'next_round', '2026-08-27 08:34:17'),
(37, 42, 41, 10, 'Needs improvement in accent and communication skills. Has knowledge of sales; but has never worked on Outlook or Excel. Comfortable with rotational shifts and weekly offs.', 'hold', '2026-08-27 09:56:56'),
(38, 43, 43, 10, 'Poor English communication skills. Not suitable for the Team Lead position. The candidate responded to the interview questions in Hindi and had not thoroughly reviewed the JD shared with him. He attended the interview under the impression that it was for a Team Lead role in sales within the IT industry, which led to the misunderstanding.', 'hold', '2026-08-27 10:28:43'),
(39, 45, 45, 10, 'Poor communication skills. The interview was conducted in Hindi, and the candidate was unable to communicate effectively in English.', 'hold', '2026-08-27 10:43:51'),
(40, 44, 44, 11, 'Ayan seems to be a good candidate for in terms of communication, experience & skill set. Supporting his father business as of now, having hotel reservation experience before. Ok for 6 days & shift timings as well. 25K is the CTC he can come on. Overall can be hired.', 'next_round', '2026-08-27 10:54:07'),
(41, 46, 44, 10, 'Good and professional communication skills with experience in the hotel industry, particularly in selling hotel packages. Comfortable working in rotational shifts and with rotational weekly offs.', 'select', '2026-08-27 11:23:27'),
(42, 42, 41, 10, 'Average communication skills and needs improvement in accent. Has not worked on Outlook or Excel previously.', 'hold', '2026-08-27 11:25:57'),
(43, 47, 50, 11, 'He has average communication. Having 5 months experience in travel, operations & sales. Handled fathers business for last one year. Now want to have his own career in travel again. Ok for 6 days, ok for shift timings. An average candidate can be trained. Interested in sales. Can be considered. Looking for 25K CTC but can come in lesser.', 'next_round', '2026-08-31 10:56:38'),
(44, 48, 50, 12, 'He should be considered for the position, he has committed to work on his communication and show an improvement in 15 days and also that he will do his best to prove himself as a worthy candidate.', 'select', '2026-08-31 12:12:00'),
(45, 49, 51, 10, 'complete fresher and new to industry. ok communication and ready to join immediately. ok with shift timings and rotational shift. Never worked on outlook we need to provide training. And has basic knowledge about excel since done computer course but never worked ever.', 'next_round', '2026-09-01 06:50:05'),
(46, 50, 52, 10, 'good communication, ok with shifts and rotational week off. can join immediately', 'next_round', '2026-09-01 07:01:52'),
(47, 51, 53, 11, 'Good Candidate, having travel visa sales experience of around 1 year. Well qualified bright, having good communication, good understanding about work & sales. Destination knowledge is missing but that is ok. Ok for 6 days & shift timings as well. 25 K CTC he is ok at. Can join tomorrow. Can be considered.', 'next_round', '2026-09-01 08:29:27'),
(48, 52, 51, 11, 'Coming from teaching career & background. Now interested in corporate & sales as well. Good communication, kind of first job & need to learn excel & outlook as well. Confident, can learn & can do. Having Rahul Rizawani reference. Ok for the shift timings & weekdays as well. Freshers can come in 20K.Can be considered.', 'select', '2026-09-01 08:58:43'),
(49, 53, 53, 10, 'ok communication and worked earlier with travel agency. Have basic knowledge about outlook and excel . on with me .can join from tomorrow. he is ok with shifts and weekly off as per company terms.', 'select', '2026-09-01 09:13:32'),
(50, 53, 53, 10, 'ok communication and worked earlier with travel agency. Have basic knowledge about outlook and excel . on with me .can join from tomorrow. he is ok with shifts and weekly off as per company terms.', 'select', '2026-09-01 09:13:32'),
(51, 54, 52, 11, 'He is a good candidate, though having school sales experience, but seems to be very good in sales pitch. He has done a BBA in Hospitality & Tourism operations. Interest in travelling & exploring destinations. Good communication, ok with shift timings & weekdays as well. Selected', 'select', '2026-09-01 09:59:58'),
(52, 55, 54, 11, 'Sarthak seems a little like going with the flow kind of a person. Not have spent more than a year in past experience, also have taken 3 months gap after every job. Still his experience is quite good, communication is good, he is ready for weekdays & Shift timings as well. 29 K was his last, he is ok for 25 CTC. Can be considered.', 'next_round', '2026-09-02 07:22:54'),
(53, 56, 54, 10, 'good communication ,well experienced and ready to join tomorrow.', 'select', '2026-09-02 09:10:58'),
(54, 57, 55, 10, 'communication is weak and was unabel to convince me on sales task assigned', 'reject', '2026-09-02 09:42:31'),
(55, 59, 56, 11, 'She is pursuing graduation, web designing along as well. Communication is not good in english, talking in hindi english both mixed. Having similar experience for 1.6 years. Ok from my side, look at communication but. Can come in 22900 CTC. Ok for shift Days & shift timings.', 'next_round', '2026-09-02 09:44:27'),
(56, 62, 56, 10, 'communication is not good at all. Though she has worked in operation but has no knowledge on destination Also.', 'reject', '2026-09-02 09:59:27'),
(57, 65, 59, 10, 'good communication but never worked on outlook , excel basic knowledge. ok with shift timings and rotational off.', 'select', '2026-09-02 11:00:39'),
(58, 60, 57, 11, 'She is ok as a PA in contracting but not for reservation, since her english communication is not good as such. Can come in PA salary. Ok for 6 days & shift timings a swell.', 'select', '2026-09-02 11:06:02'),
(59, 63, 58, 11, 'Not good for any open position. Neither contracting & nor in reservation. Her salary is at higher side & her communication is poor so cannot be recommended.', 'reject', '2026-09-02 11:24:33'),
(60, 66, 60, 11, 'Not suitable for Reservation sales, communication issues. But can be considered for contracting. She is preparing for Civil Services for long time. Now want to join private sector. Ok for 6 days work as well. Salary expectation 16 to 20K.', 'select', '2026-09-03 07:06:34'),
(61, 67, 62, 11, 'Kanishka seems to be a good candidate. Having 4 years travel industry experience, contracting loading & Checking. She has a immunity disorder due to which her 30% kidneys are working only. She is on medication, but it does not affect her routine life. Interested in 11.30 to 8.30 Shift. Ok for 6 days working. Sarthak\'s reference. Salary expectation is high, asking for 35 K, has offer in hand for 35 K. Serving notice in current company. Can be looked at as TL for new process. Communication is good.', 'next_round', '2026-09-03 07:49:45'),
(62, 68, 61, 11, 'Aditya seems to be a Ok candidate. Having experience in BPO & Sales. He needs job right now, communication is average. Ok for sales reservation profile, ok for 6 days & shift timings. Can join tomorrow. Last salary is 28K, can come in 25500 CTC. Can be hired.', 'next_round', '2026-09-03 08:23:45'),
(63, 69, 65, 11, 'Fresher, average communication, need of job, issues with father staying alone, little hesitant but showing interest in sales. ok for 6 days shift & shift hours.  Pls check on salary as well. He was getting 12K CTC in last company. Can be trained & hired.', 'next_round', '2026-09-03 11:22:27'),
(64, 70, 66, 11, 'Raveena is a fresher, looking for good opportunity, need job asap, her father is not well for last 3 months. She seems ok for sales & confident about the role. Salary expectation is 25000. we have conveyed 20K CTC, she will discuss with family & confirm. Communication Average, ok for 6 days & shift hours.', 'next_round', '2026-09-03 11:47:33'),
(65, 71, 65, 10, 'Complete fresher with basic knowledge of Excel and Outlook. Currently has an offer from SBI Cards with ? 20,000 in hand and is looking for ? 25,000. ok with shifts and rotational off. changing job for salary finds confused and stability issue.', 'hold', '2026-09-03 11:57:36'),
(66, 72, 67, 11, 'Gazal is good in communication, having exposure of her own business with her father (Gems & Stones). Pursuing final year of graduation since she had dropped it before due to family circumstances. Confident for sales. Worked in same company Kunal worked. Both were colleagues. Ok for 6 days shift & shift hours. Can be hired. Salary expectation is 24K but is negotiable.', 'next_round', '2026-09-03 12:09:04'),
(67, 74, 66, 10, 'The candidate is a complete fresher and is seeking a salary of up to ?30,000 per month. She has already received an offer from Teleperformance. When asked about her salary expectations, she mentioned that she is the sole earning member of her family, which is the primary reason for expecting a higher salary package.', 'hold', '2026-09-03 12:24:27'),
(68, 75, 69, 11, 'Communication is average, willing for sales, seems confident. Having 6 months experience in Jewelry company in customer handling & back-office work. Basically, from Ajmer living in Jaipur with cousins. 6 days a week, only ok for morning shift.  20 K CTC she is ok at.', 'next_round', '2026-09-03 12:43:01'),
(69, 76, 67, 10, 'ok communication and worked on outlook and excel. 24 k negotiable and immedate joiner. she wants to know salary than only she will join based on that she will decide. she wants to earn more than her brother .', 'select', '2026-09-03 13:18:44'),
(70, 77, 69, 10, 'worked on outlook and excel but on shift timings she wants only day shift 9:30 to 6:30 pm.ok with rotational off.', 'select', '2026-09-03 13:52:28'),
(71, 78, 70, 11, 'Communication average, willing to do sales, pursuing B.Tech from MNIT but not interested since the parents want she is doing it, can do but needs grooming, has experience of 3 months in sales. Ready for commitment. Ok for 6 days week & morning shift only, 9.30 to 6.30. Salary 20K CTC. Ready to join from Monday.', 'next_round', '2026-09-04 06:12:30'),
(72, 79, 70, 10, 'The candidate\'s communication skills require improvement. She has no prior experience working with Microsoft Outlook or Excel. Additionally, her pronunciation needs further development, which may impact overall communication effectiveness.\r\nwas unable to sell me mobile phone', 'reject', '2026-09-04 07:06:13'),
(73, 80, 73, 11, 'Abhimanyu seems ok to me since his communication is average, he studied Tourism & Hospitality. Dropped LLB since he could not clear it there is a gap. He has only done internship so far, no experience as such. Ok for 6 days a week & shift timing. Basically, from Jodhpur but living in Jaipur with mother. father is in Policy posted in Biawar. Ok for sales. Can be considered . Ok for 20K CTC', 'next_round', '2026-09-07 09:38:01'),
(74, 81, 73, 12, 'He is a decent candidate and can be considered. Will need hand-holding, training and guidance on Memorizing skills, temper management and being patient. Other than that, he has a decent command over his language. \r\n\r\nCan be considered for a post, keeping in mind the above.', 'select', '2026-09-07 10:10:03'),
(75, 82, 74, 11, 'Siddhi has ok communication, but seems enthusiastic & reliable. She has 4 months experience in a call center as PA. She did Quit there since the process got ramped down.  Living in mansarovar, ok for 6 days, shift timings as well. 20K CTC can be offered.', 'next_round', '2026-09-08 05:53:49'),
(76, 84, 41, 12, 'Can be considered, he seems an intelligent and committed young man. We can go ahead with him.', 'select', '2026-09-08 07:41:24'),
(77, 85, 74, 12, 'Can be considered for a position. She communicates well and has a pleasant personality. Has the skills and intelligence. Can be a long term candidate for us.', 'select', '2026-09-08 08:12:59'),
(78, 83, 75, 11, 'Vaibhav has no experience; communication is also average. No zeal & enthusiasm & for work. Asking for 24 K, not suitable for any position.', 'reject', '2026-09-08 09:32:15'),
(79, 86, 70, 12, 'She is communicative and can speak, but not fit for the Reservations Executive. May be considered for another position later.', 'hold', '2026-09-08 10:19:30'),
(80, 87, 77, 11, 'Reena is a fresher, having good communication, a decent candidate, ok for sales. 6 days week, but 9.30 to 6.30 only she can work, no evening shift. Can be considered. 20K CTC is ok', 'next_round', '2026-09-09 05:17:34'),
(81, 88, 78, 11, 'Lakshay is a good candidate, academically strong, good communication skills, did 3 years diploma in German language. Having only 3 months experience in sales. Left last job due to conflicts with TL. Temperament may be an issue. Ok for 6 days & shift timings. 20 k can be offered as CTC. Can be considered for reservation sales', 'next_round', '2026-09-09 05:59:49'),
(82, 89, 79, 11, 'Pushpanjali is an ex employee. Was working in Itrip before. Left due to her family issues. Now she is separated & living with parents in Mansarovar only. Her last drawn salary is 21200. We can discuss her salary & close her for 6 days shift. She can join from tomorrow.', 'select', '2026-09-09 06:13:26'),
